/* ===== src/js/47-card.js ===== */
/* ==========================================================================
   Card: the rows of a panel list switch layout together
   --------------------------------------------------------------------------
   A panel's .card__list is a column of links with a count at the end ("Shapes  12"). Row by
   row, a count that did not fit dropped under its link while the others stayed beside it. This
   measures the whole list with SG.fit (05-fit.js) and writes data-fit on it; card.css draws:

     row     every count beside its link (the link's words wrap beside it)
     stack   every count under its link, aligned with the link's first letter

   It re-checks when the list's size changes and when a list is added. Without JS there is no
   data-fit and each row wraps on its own.

   API   SG.card.fit()   re-check every panel list now
   ========================================================================== */
(function (SG) {
  'use strict';

  SG.fit.register('.card__list', {
    steps: ['row', 'stack'],
    /* in row mode a link that cannot hold its longest word beside the count overflows (card.css) */
    parts: '.card__list > li, .card__list > li > a'
  });

  SG.card = { fit: SG.fit.update };
})((window.SG = window.SG || {}));
